out=[];bad=[]
for r in rows:
 if r['status']=='verified':continue
 assert r['id'] in M,r['id'];files,contracts,tests=M[r['id']];controls=r['requestedControls'].split('、');assert len(controls)==len(contracts),(r['id'],len(controls),len(contracts))
 fs=[]
 for name in files:
  p=root/'templates/angular'/name
  if not p.exists():bad.append({'id':r['id'],'missingFile':str(p)});continue
  fs.append({'path':'templates/angular/'+name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
 ts=[]
 for name in tests:
  p=root/'tests/ui'/name
  if not p.exists():bad.append({'id':r['id'],'missingTest':str(p)});continue
  ts.append({'path':'tests/ui/'+name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'kind':'formal test source reviewed; actual final run belongs to root evidence'})
 out.append({'id':r['id'],'component':r['component'],'originalRequestedControls':r['requestedControls'],'sourceLine':r.get('sourceLine'),'controlMapping':[{'requested':a,'publicRuntimeContract':b} for a,b in zip(controls,contracts)],'implementationSources':fs,'formalTestReferences':ts,'controlOmissionsObserved':[],'verdict':'public implementation mapped; formal final suite results are owned by root evidence, not invented by this mapping'})
